-- =====================================================================
--  SQL Interview Practice Database
--  Seed data for the 9-chapter SQL interview question set
--  Generated 2026-08-23  |  reference "today" = 2026-07-26
--  300 users · 990 orders · 1455 order lines
--  132 products · 3093 sales · 7151 logins
-- =====================================================================
CREATE TABLE categories (
  category_id   INTEGER PRIMARY KEY,
  category_name VARCHAR(50) NOT NULL
);

-- 6 rows into categories


CREATE TABLE departments (
  dept_id   INTEGER PRIMARY KEY,
  dept_name VARCHAR(50) NOT NULL
);

-- 6 rows into departments


CREATE TABLE users (
  user_id         INTEGER PRIMARY KEY,
  user_name       VARCHAR(50),
  username        VARCHAR(50),
  first_name      VARCHAR(30),
  last_name       VARCHAR(30),
  phone           VARCHAR(20),
  email           VARCHAR(120),
  age             INTEGER,
  birth_date      DATE,
  gender          VARCHAR(10),
  city            VARCHAR(30),
  province        VARCHAR(30),
  address         VARCHAR(200),
  status          VARCHAR(20),
  register_ip     VARCHAR(45),
  register_date   DATE,
  register_time   TIMESTAMP,
  last_login_time TIMESTAMP,
  last_order_time TIMESTAMP
);

-- 300 rows into users



CREATE TABLE products (
  product_id     INTEGER PRIMARY KEY,
  product_name   VARCHAR(200),
  name           VARCHAR(200),
  price          DECIMAL(10,2),
  category_id    INTEGER,
  category_big   VARCHAR(50),
  category_small VARCHAR(50),
  stock          INTEGER
);

-- 132 rows into products


CREATE TABLE orders (
  order_id       INTEGER PRIMARY KEY,
  user_id        INTEGER,
  product_id     INTEGER,
  category_id    INTEGER,
  amount         DECIMAL(10,2),
  quantity       INTEGER,
  status         VARCHAR(20),
  pay_status     VARCHAR(20),
  payment_method VARCHAR(20),
  coupon_id      INTEGER,
  province       VARCHAR(30),
  buyer_nick     VARCHAR(50),
  order_date     DATE,
  order_time     TIMESTAMP,
  pay_time       TIMESTAMP,
  create_time    TIMESTAMP
);

-- 990 rows into orders






CREATE TABLE order_details (
  id         INTEGER PRIMARY KEY,
  order_id   INTEGER,
  user_id    INTEGER,
  product_id INTEGER,
  category_id INTEGER,
  quantity   INTEGER,
  price      DECIMAL(10,2)
);

-- 1455 rows into order_details









CREATE VIEW order_items AS
  SELECT order_id, product_id, quantity FROM order_details;

CREATE TABLE employees (
  emp_id      INTEGER PRIMARY KEY,
  name        VARCHAR(50),
  dept_id     INTEGER,
  department  VARCHAR(50),
  gender      VARCHAR(10),
  salary      DECIMAL(10,2),
  hire_date   DATE,
  manager_id  INTEGER,
  buyer_nick  VARCHAR(50)
);

-- 60 rows into employees


CREATE VIEW employee AS SELECT emp_id, name, dept_id, salary, hire_date, manager_id FROM employees;

CREATE TABLE students (
  student_id INTEGER PRIMARY KEY,
  name       VARCHAR(50),
  class_id   INTEGER,
  score      DECIMAL(5,2)
);

-- 120 rows into students


CREATE TABLE scores (
  student_id INTEGER,
  course_id  VARCHAR(20),
  score      DECIMAL(5,2)
);

-- 408 rows into scores




CREATE VIEW score AS SELECT s.student_id, st.class_id, s.score FROM scores s JOIN students st ON s.student_id = st.student_id;

CREATE TABLE course_selection (
  student_id INTEGER,
  course_id  VARCHAR(20)
);

-- 408 rows into course_selection




CREATE TABLE shops (
  shop_id   INTEGER PRIMARY KEY,
  shop_name VARCHAR(100)
);

-- 20 rows into shops


CREATE TABLE reviews (
  review_id   INTEGER PRIMARY KEY,
  user_id     INTEGER,
  product_id  INTEGER,
  shop_id     INTEGER,
  rating      INTEGER,
  content     VARCHAR(500),
  review_time TIMESTAMP
);

-- 1400 rows into reviews








CREATE VIEW review AS SELECT review_id, user_id, product_id, rating FROM reviews;

CREATE TABLE articles (
  article_id INTEGER PRIMARY KEY,
  title      VARCHAR(200),
  tags       VARCHAR(300)
);

-- 40 rows into articles


CREATE TABLE comments (
  comment_id   INTEGER PRIMARY KEY,
  article_id   INTEGER,
  user_id      INTEGER,
  content      TEXT,
  comment_time TIMESTAMP,
  created_at   TIMESTAMP
);

-- 900 rows into comments






CREATE TABLE likes (
  like_id    INTEGER PRIMARY KEY,
  article_id INTEGER,
  user_id    INTEGER,
  like_time  TIMESTAMP
);

-- 2600 rows into likes














CREATE TABLE access_log (
  log_id      INTEGER PRIMARY KEY,
  user_id     INTEGER,
  session_id  VARCHAR(40),
  ip          VARCHAR(45),
  page        VARCHAR(60),
  access_time TIMESTAMP
);

-- 1941 rows into access_log











CREATE TABLE visit_log (
  id         INTEGER PRIMARY KEY,
  user_id    INTEGER,
  visit_time TIMESTAMP
);

-- 5320 rows into visit_log




























CREATE TABLE login_logs (
  id         INTEGER PRIMARY KEY,
  user_id    INTEGER,
  login_date DATE,
  login_time TIMESTAMP
);

-- 7151 rows into login_logs





































CREATE TABLE follow (
  follower_id INTEGER,
  followee_id INTEGER
);

-- 2798 rows into follow















CREATE TABLE sales (
  sale_id     INTEGER PRIMARY KEY,
  product_id  INTEGER,
  category_id INTEGER,
  salesperson VARCHAR(50),
  sale_date   DATE,
  amount      DECIMAL(10,2),
  quantity    INTEGER
);

-- 3093 rows into sales

















CREATE TABLE inventory (
  product_id     INTEGER,
  as_of_date     DATE,
  stock_quantity INTEGER
);

-- 1320 rows into inventory








CREATE TABLE monthly_sales (
  year_month VARCHAR(7) PRIMARY KEY,
  sales      DECIMAL(12,2)
);

-- 31 rows into monthly_sales


CREATE TABLE "returns" (
  return_id   INTEGER PRIMARY KEY,
  order_id    INTEGER,
  return_time TIMESTAMP
);

-- 89 rows into "returns"


CREATE TABLE events (
  event_id   INTEGER PRIMARY KEY,
  user_id    INTEGER,
  session_id VARCHAR(40),
  event_type VARCHAR(20),
  event_time TIMESTAMP
);

-- 1556 rows into events









CREATE VIEW user_events AS SELECT user_id, session_id, event_type, event_time FROM events;

CREATE TABLE impressions (
  impression_id   INTEGER PRIMARY KEY,
  content_id      INTEGER,
  user_id         INTEGER,
  impression_time TIMESTAMP
);

CREATE TABLE clicks (
  click_id   INTEGER PRIMARY KEY,
  content_id INTEGER,
  user_id    INTEGER,
  click_time TIMESTAMP
);

-- 14068 rows into impressions








































































-- 1436 rows into clicks









CREATE TABLE blacklist (
  user_id     INTEGER PRIMARY KEY,
  reason      VARCHAR(100),
  created_at  TIMESTAMP
);

-- 18 rows into blacklist


CREATE TABLE event_participation (
  user_id  INTEGER,
  event_id VARCHAR(10)
);

-- 338 rows into event_participation



CREATE TABLE exp_users (
  user_id    INTEGER PRIMARY KEY,
  group_flag VARCHAR(10)
);

-- 300 rows into exp_users



CREATE TABLE stock_price (
  trade_date  DATE PRIMARY KEY,
  close_price DECIMAL(10,2)
);

-- 147 rows into stock_price


CREATE TABLE transactions (
  trans_id   INTEGER PRIMARY KEY,
  user_id    INTEGER,
  trans_date DATE,
  amount     DECIMAL(10,2)
);

-- 1035 rows into transactions







CREATE TABLE videos (
  video_id         INTEGER PRIMARY KEY,
  title            VARCHAR(200),
  duration_seconds INTEGER
);

-- 30 rows into videos


CREATE TABLE tickets (
  ticket_id  INTEGER PRIMARY KEY,
  user_id    INTEGER,
  subject    VARCHAR(200),
  created_at TIMESTAMP
);

-- 240 rows into tickets



CREATE TABLE websites (
  site_id INTEGER PRIMARY KEY,
  url     VARCHAR(500)
);

-- 10 rows into websites


CREATE TABLE user_address (
  user_id   INTEGER PRIMARY KEY,
  province  VARCHAR(30),
  city      VARCHAR(30),
  district  VARCHAR(30),
  detail    VARCHAR(200)
);

-- 300 rows into user_address



CREATE TABLE user_activity (
  user_id       INTEGER,
  activity_date DATE,
  active_month  VARCHAR(7)
);

-- 2884 rows into user_activity
















CREATE TABLE parts (
  part_id VARCHAR(30) PRIMARY KEY,
  cost    DECIMAL(10,2)
);

CREATE TABLE bom (
  part_id      VARCHAR(30),
  component_id VARCHAR(30),
  quantity     INTEGER
);

-- 8 rows into parts


-- 11 rows into bom


CREATE VIEW sales_2025 AS SELECT sale_id AS order_id, amount FROM sales WHERE sale_date < '2026-01-01';

CREATE VIEW sales_2026 AS SELECT sale_id AS order_id, amount FROM sales WHERE sale_date >= '2026-01-01';

CREATE VIEW orders_2025 AS SELECT order_id, user_id, amount FROM orders WHERE order_date < '2026-01-01';

CREATE VIEW orders_2026 AS SELECT order_id, user_id, amount FROM orders WHERE order_date >= '2026-01-01';

CREATE VIEW users_v1 AS SELECT user_id, user_name AS name, phone, register_time AS create_time FROM users WHERE user_id <= 250;

CREATE VIEW users_v2 AS SELECT user_id, user_name AS name, phone, register_time AS create_time FROM users WHERE user_id >= 100;

CREATE VIEW logs AS SELECT log_id AS id, user_id, page AS action, access_time AS log_time FROM access_log;

CREATE VIEW daily_sales AS SELECT sale_date, SUM(amount) AS amount FROM sales GROUP BY sale_date;

CREATE VIEW sales_person AS SELECT ROW_NUMBER() OVER (ORDER BY salesperson) AS id, salesperson AS name, SUM(amount) AS total_sales FROM sales GROUP BY salesperson;

